"""Packing n=26: maximize uniform radius r via bisection + local fit."""
import numpy as np


def _feasible(centers, r):
    n = len(centers)
    for i in range(n):
        x, y = centers[i]
        if x < r or x > 1 - r or y < r or y > 1 - r:
            return False
    for i in range(n):
        for j in range(i + 1, n):
            if np.hypot(centers[i][0] - centers[j][0],
                        centers[i][1] - centers[j][1]) < 2 * r:
                return False
    return True


def _local_fit(centers, r, iters=40, step0=0.03):
    """Try to make all circles of radius r fit by nudging centers."""
    centers = np.array(centers, dtype=float)
    n = len(centers)
    for it in range(iters):
        if _feasible(centers, r):
            break
        step = step0 * (0.92 ** it)
        improved = False
        for i in range(n):
            x, y = centers[i]
            if x < r or x > 1 - r or y < r or y > 1 - r:
                continue
            # count violations for i
            def viol(px, py):
                if px < r or px > 1 - r or py < r or py > 1 - r:
                    return 999
                v = 0.0
                for j in range(n):
                    if j == i:
                        continue
                    d = np.hypot(px - centers[j][0], py - centers[j][1])
                    if d < 2 * r:
                        v += (2 * r - d)
                return v
            cur = viol(x, y)
            if cur <= 0:
                continue
            for dx in (-step, 0, step):
                for dy in (-step, 0, step):
                    if dx == 0 and dy == 0:
                        continue
                    nv = viol(x + dx, y + dy)
                    if nv < cur - 1e-9:
                        centers[i] = [x + dx, y + dy]
                        cur = nv
                        improved = True
        if not improved:
            break
    return centers


